// Builds public/data/benchmark-results.json from the authoritative, committed
// public/data/all-pairs-search.json.
//
// The artifact is a small, deterministic aggregate the browser can import: the
// 11.9 MB all-pairs file carries traces and cannot ship in the client bundle.
// Everything here is derived, so the file can be regenerated byte-for-byte and a
// freshness gate can compare it -- no runtime numbers and no timestamp, both of
// which would make the artifact unreproducible.
//
// Runtime is deliberately absent. Native timings vary run to run and machine to
// machine (see scripts/verify_all_runtimes.mjs) and ship separately in
// public/data/all-pairs-runtime.json; they must never be relabelled as browser
// measurements (CLAUDE.md I5).

export const LABELS = { ucs: "UCS", astar: "Current-flow A*" };
export const ALGORITHMS = ["ucs", "astar"];

// The canonical sample route: the same Arad -> Bucharest pair the committed
// public/data/arad-bucharest-search.json traces.
export const SAMPLE_START = 0;
export const SAMPLE_GOAL = 12;

export function round1(value) {
  return Math.round(value * 10) / 10;
}

function algorithmResults(pairs) {
  return ALGORITHMS.map((algorithm) => ({
    algorithm,
    label: LABELS[algorithm],
    expanded: pairs.reduce((sum, pair) => sum + pair[algorithm].expanded, 0),
  }));
}

export function buildBenchmarkResults(allPairs) {
  const [ucs, astar] = algorithmResults(allPairs.pairs);
  const expandedReduction = ucs.expanded - astar.expanded;
  const optimalCostMismatches = allPairs.pairs.filter(
    (pair) => pair.ucs.cost !== pair.astar.cost,
  ).length;

  const sample = allPairs.pairs.find(
    (pair) => pair.start === SAMPLE_START && pair.goal === SAMPLE_GOAL,
  );
  if (!sample) {
    throw new Error(
      `all-pairs data has no ${SAMPLE_START} -> ${SAMPLE_GOAL} sample route`,
    );
  }
  const start = allPairs.cities.find((city) => city.id === SAMPLE_START);
  const goal = allPairs.cities.find((city) => city.id === SAMPLE_GOAL);
  if (!start || !goal) {
    throw new Error("all-pairs data is missing sample-route city metadata");
  }

  return {
    schema_version: 2,
    source: "public/data/all-pairs-search.json",
    all_pairs: {
      city_count: allPairs.city_count,
      route_count: allPairs.pair_count,
      includes_same_city_routes: allPairs.includes_same_city_pairs,
      results: [ucs, astar],
      comparison: {
        expanded_reduction: expandedReduction,
        expanded_reduction_percent: round1((expandedReduction / ucs.expanded) * 100),
        optimal_cost_mismatches: optimalCostMismatches,
      },
    },
    sample_route: {
      start: { id: start.id, name: start.name },
      goal: { id: goal.id, name: goal.name },
      cost_km: sample.ucs.cost,
      results: ALGORITHMS.map((algorithm) => {
        const result = sample[algorithm];
        return {
          algorithm,
          label: LABELS[algorithm],
          expanded: result.expanded,
          generated: result.generated,
          peak_frontier: result.peak_frontier,
          peak_records: result.peak_records,
          peak_payload_bytes: result.peak_payload_bytes,
        };
      }),
      comparison: {
        expanded_reduction_percent: round1(
          ((sample.ucs.expanded - sample.astar.expanded) / sample.ucs.expanded) * 100,
        ),
        peak_payload_reduction_percent: round1(
          ((sample.ucs.peak_payload_bytes - sample.astar.peak_payload_bytes) /
            sample.ucs.peak_payload_bytes) *
            100,
        ),
      },
    },
    method: {
      runtime:
        "native per-pair timings are not embedded here; they ship separately in public/data/all-pairs-runtime.json. That file is a historical sample exported by wasm/src/bin/export_all_runtimes.rs (native release build); the run's source revision and machine are unrecorded, so it is not current validated-engine performance.",
      memory:
        "peak_payload_bytes is the search-state payload in bytes. It excludes trace, container, and allocator overhead and is not total process memory or RSS.",
    },
  };
}

export function serializeBenchmarkResults(results) {
  return JSON.stringify(results, null, 2) + "\n";
}
